def color_func(Y, mode='polygon', global_bounds=None):
    if mode == 'polygon':
        # 細胞外觀顯示「mRNA」
        norm = (Y[:, 0] - Y[:, 0].min()) / (np.ptp(Y[:, 0]) + 1e-8)
        return plt.cm.inferno(norm)
    elif mode == 'center':
        # 細胞中心點顯示「inhibitor」
        norm = (Y[:, 1] - Y[:, 1].min()) / (np.ptp(Y[:, 1]) + 1e-8)
        return plt.cm.BuGn(norm)
    else:
        return None
